import { describe, expect, it } from 'vitest';
import plugin from './withReleaseSigning.js';

const { applyReleaseSigning } = plugin;

// The relevant part of android/app/build.gradle as generated by `expo prebuild` (SDK 57).
const TEMPLATE = `android {
    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }
    buildTypes {
        debug {
            signingConfig signingConfigs.debug
        }
        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug
            def enableShrinkResources = findProperty('android.enableShrinkResourcesInReleaseBuilds') ?: 'false'
        }
    }
}`;

describe('applyReleaseSigning', () => {
  it('adds a release signing config read from the environment', () => {
    const out = applyReleaseSigning(TEMPLATE);
    expect(out).toContain("storeFile file(System.getenv('RELEASE_STORE_FILE'))");
    expect(out).toContain("keyAlias System.getenv('RELEASE_KEY_ALIAS')");
  });

  it('signs release builds with it when RELEASE_STORE_FILE is set, debug otherwise', () => {
    const out = applyReleaseSigning(TEMPLATE);
    expect(out).toContain("signingConfig System.getenv('RELEASE_STORE_FILE') ? signingConfigs.release : signingConfigs.debug");
    // the debug build type is untouched
    expect(out).toMatch(/debug \{\s*signingConfig signingConfigs\.debug\s*\}/);
  });

  it('is idempotent', () => {
    const once = applyReleaseSigning(TEMPLATE);
    expect(applyReleaseSigning(once)).toBe(once);
  });

  it('fails loudly when the template no longer matches', () => {
    expect(() => applyReleaseSigning('android { buildTypes { release { } } }')).toThrow('withReleaseSigning');
  });
});
